```c
#include <stdio.h>

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int G[100][100];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            scanf("%d", &G[i][j]);
        }
    }

    long long cost[2] = {0, 0};

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int parity = G[i][j] & 1;
            int target0 = (i + j) & 1;

            if (parity != target0) cost[0]++;
            if (parity != (1 - target0)) cost[1]++;
        }
    }

    int best = (cost[0] <= cost[1]) ? 0 : 1;

    printf("%lld\n", cost[best]);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int target = ((i + j) & 1) ^ best;
            int val = G[i][j];

            if ((val & 1) != target) {
                val++;
            }

            if (j > 0) printf(" ");
            printf("%d", val);
        }
        printf("\n");
    }

    return 0;
}
```

